            0x0E: 0x00,  # PORT3_STATUS
            0x0F: 0x00,  # PORT4_STATUS
            0x10: 0x00,  # POWER_STATUS
            0x17: 0x80,  # GENERAL_MASK
            0x18: 0x00,  # RESTART
            0x19: 0x00,  # POWER_ENABLE
            0x1A: 0x00,  # RESET_CMD
            0x27: 0x00,  # INTERRUPT_TIMER
            0x2C: 0x00,  # TEMPERATURE
            0x40: 0x00,  # POE_PLUS
            0xFE: 0x00   # FIRMWARE_REV
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr in self.regs:
            value = self.regs[addr]
            return value & ((1 << nbytes * 8) - 1)
        else:
            raise ValueError(f"Register address {addr} does not exist.")

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr in self.regs:
            if nbytes == 1:
                # Single byte access: update only bits 15:8
                self.regs[addr] = (self.regs[addr] & 0xFF00) | (data & 0xFF)
            else:
                # Full register read/write
                self.regs[addr] = data
        else:
            raise ValueError(f"Register address {addr} does not exist.")

